states.d42da8d33059:
{
 "bugun": "2026-10-01",
 "izahname_ozeti": {
  "sirket": "Gökçeada Yenilenebilir Enerji Üretim A.Ş. (GKENR)",
  "sirket_hakkinda": "Şirket 2014 yılında kurulmuş olup Çanakkale, Balıkesir ve İzmir'de toplam 412 MW kurulu güce sahip rüzgâr santralleri ile Konya'da 96 MWp güneş santrali işletmektedir. Üretilen elektriğin yaklaşık %60'ı serbest piyasada, kalanı ikili anlaşmalarla satılmaktadır. 2025 yılında şirketin elektrik üretimi 1.380 GWh, hasılatı 6,9 milyar TL olarak gerçekleşmiştir. Şirketin 31.12.2025 itibarıyla 412 çalışanı bulunmaktadır.",
  "halka_arz_yapisi": "Halka arzda 1 TL nominal değerli toplam 75.000.000 adet pay satışa sunulacaktır. Bunun 60.000.000 adedi sermaye artırımı yoluyla yeni ihraç edilecek paylardan, 15.000.000 adedi ise mevcut ortak Ada Enerji Yatırımları A.Ş.'nin sahip olduğu payların satışından oluşmaktadır. Halka arz fiyatı pay başına 24,80 TL'dir. Satış, Borsa İstanbul'da sabit fiyatla talep toplama ve satış yöntemiyle yapılacaktır.",
  "dagitim_plani": "Satışa sunulan payların %35'i yurt içi bireysel yatırımcılara, %15'i yurt içi yüksek başvurulu yatırımcılara, %30'u yurt içi kurumsal yatırımcılara, %20'si yurt dışı kurumsal yatırımcılara tahsis edilmiştir. Bir yatırımcı grubuna yapılan tahsisatın karşılanamaması halinde, karşılanamayan paylar konsorsiyum lideri tarafından diğer gruplara aktarılabilir.",
  "fon_kullanim_yerleri": "Sermaye artırımından elde edilecek net gelirin yaklaşık %55'i Konya'daki 150 MWp kapasiteli yeni güneş santrali yatırımında, %30'u yabancı para cinsi yatırım kredilerinin erken kapatılmasında, %15'i işletme sermayesi ihtiyacında kullanılacaktır. Ortak satışından elde edilecek gelir şirkete değil, satış yapan ortağa ait olacaktır.",
  "fiyat_istikrari": "Konsorsiyum lideri, payların borsada işlem görmeye başladığı tarihten itibaren 30 gün süreyle, halka arzdan elde edilecek brüt gelirin %10'una kadar olan tutarla fiyat istikrarını sağlayıcı işlemler yapabilecektir. Bu işlemlerde halka arz fiyatının üzerinde alım emri verilemez.",
  "satmama_taahhudu": "Mevcut ortaklar, payların borsada işlem görmeye başladığı tarihten itibaren 1 yıl süreyle borsada pay satmayacaklarını; şirket de aynı süre boyunca bedelli sermaye artırımı yapmayacağını taahhüt etmiştir.",
  "risk_faktorleri": [
   "Elektrik fiyatları: Serbest piyasa takas fiyatlarındaki dalgalanmalar ile azami uzlaştırma fiyatı uygulamalarına ilişkin düzenleyici değişiklikler hasılatı olumsuz etkileyebilir.",
   "Rüzgâr ve güneşlenme koşulları: Üretim, meteorolojik koşullara bağlıdır; uzun süreli düşük rüzgâr dönemleri üretim hedeflerinin altında kalınmasına yol açabilir.",
   "Kur riski: Şirketin yatırım kredilerinin önemli bir kısmı avro cinsindendir; Türk lirasındaki değer kaybı finansman giderlerini artırabilir.",
   "Lisans ve izinler: Santrallerin üretim lisanslarının yenilenmemesi, kapasite artışı izinlerinin gecikmesi ya da çevresel etki değerlendirme süreçlerinin uzaması yatırım takvimini etkileyebilir.",
   "Şebeke kısıtları: İletim sistemindeki kapasite sınırlamaları nedeniyle zaman zaman yük atma talimatları verilmekte olup bu durum satılabilir üretimi azaltabilir.",
   "Tedarik zinciri: Türbin ve panel tedarikinde yaşanabilecek gecikmeler ve fiyat artışları yeni yatırımların maliyetini yükseltebilir.",
   "Sigorta: Doğal afetler veya ekipman arızaları nedeniyle oluşabilecek zararların tamamı sigorta teminatı kapsamında olmayabilir."
  ],
  "sektor_bilgisi": "Türkiye'de rüzgâr ve güneş kurulu gücü son beş yılda hızla artmış, toplam kurulu güç içindeki payları önemli ölçüde yükselmiştir. Kamu politikaları yenilenebilir kaynaklara yönelik yeni kapasite tahsislerini sürdürmekte, depolamalı santral başvuruları da gündemde yer almaktadır. Bununla birlikte, şebeke yatırımlarının kapasite artışına yetişip yetişmeyeceği sektörde tartışma konusudur. Sektördeki şirketlerin önemli bir bölümü yatırımlarını döviz cinsi uzun vadeli kredilerle finanse etmektedir. Son yıllarda yatırımcıların enerji şirketlerini değerlendirirken kurulu güç büyümesi, kapasite kullanım oranları, kredi vade yapısı ve satış anlaşmalarının süresi gibi göstergelere ağırlık verdiği görülmektedir. Ayrıca uluslararası finans kuruluşlarının yeşil kredi ve sürdürülebilirlik bağlantılı finansman imkânları, sektörde finansman maliyetlerini düşürmeye yönelik önemli bir seçenek olarak öne çıkmaktadır. Hibrit santral uygulamaları ve depolama yatırımları da önümüzdeki dönemde sektörün gündeminde kalmaya devam edecektir."
 },
 "kap_bildirimleri": [
  {
   "tarih": "2026-08-28 19:10",
   "konu": "Halka Arz Talep Toplama Sonuçları",
   "metin": "25-26-27 Ağustos 2026 tarihlerinde gerçekleştirilen talep toplama sonucunda, satışa sunulan 75.000.000 adet paya karşılık toplam 217.500.000 adet talep gelmiş olup halka arz 2,9 kat talep görmüştür. Yurt içi bireysel yatırımcılardan gelen talep, bu gruba ayrılan payın 6,1 katı olmuştur. Yurt dışı kurumsal yatırımcılardan gelen talep tahsisatı karşılamadığından, bu gruba ayrılan paylardan 6.000.000 adedi yurt içi bireysel yatırımcılara aktarılmıştır. Halka arza toplam 1.640.000 yatırımcı katılmıştır. Payların 01.09.2026 tarihinde Borsa İstanbul Yıldız Pazar'da işlem görmeye başlaması beklenmektedir."
  },
  {
   "tarih": "2026-09-01 18:35",
   "konu": "Özel Durum Açıklaması (Genel)",
   "metin": "Şirketimiz payları bugün Borsa İstanbul'da işlem görmeye başlamış olup ilk işlem günü kapanış fiyatı 27,28 TL olarak gerçekleşmiştir."
  },
  {
   "tarih": "2026-09-08 18:50",
   "konu": "Fiyat İstikrarı İşlemlerine İlişkin Bildirim",
   "metin": "Konsorsiyum lideri tarafından 03.09.2026 – 07.09.2026 tarihleri arasında fiyat istikrarını sağlayıcı işlemler kapsamında toplam 1.150.000 adet pay, ortalama 23,95 TL fiyattan alınmıştır."
  },
  {
   "tarih": "2026-09-30 19:05",
   "konu": "Fiyat İstikrarı İşlemlerine İlişkin Bildirim",
   "metin": "Fiyat istikrarını sağlayıcı işlemlerin süresi 30.09.2026 itibarıyla sona ermiştir. Süre boyunca konsorsiyum lideri tarafından yapılan alımların toplamı 2.400.000 adet pay olup ortalama alış fiyatı 24,02 TL'dir. Alınan payların elden çıkarılmasına ilişkin bilgiler ayrıca kamuya açıklanacaktır."
  }
 ],
 "arastirma_notu": "Halka arzın ilk haftasında yaşanan sert dalgalanma, enerji hisselerinde sektör genelindeki satış baskısıyla eş zamanlı gerçekleşti. Rakip yenilenebilir enerji şirketlerinin hisseleri aynı dönemde ortalama %7 geriledi. Şirketin 2026 ikinci yarı üretim tahmini 720 GWh olup ilk yarı gerçekleşmesi 655 GWh'tir. Konya'daki yeni güneş santralinin 2028 başında devreye alınması planlanıyor. Notta ayrıca şirketin avro cinsi kredilerinin vade yapısı, son dönemde yükselen serbest piyasa fiyatları ve bayram dönemlerinde azalan tüketim nedeniyle düşen talebe ilişkin genel değerlendirmeler yer alıyor; bu değerlendirmelerin hiçbiri yatırım tavsiyesi niteliği taşımaz.",
 "finansal_ozet": "Şirketin 2025 yılı FAVÖK'ü 4,1 milyar TL, net dönem kârı 1,3 milyar TL olarak gerçekleşmiştir. 31.12.2025 itibarıyla net finansal borç 9,8 milyar TL, net borç/FAVÖK oranı 2,4 kattır. 2024 yılında şirket, Balıkesir'deki rüzgâr santraline 42 MW'lık kapasite artışı yapmış ve bu yatırımı büyük ölçüde avro cinsi kredilerle finanse etmiştir. Şirketin son üç yıllık ortalama kapasite kullanım oranı rüzgâr santrallerinde %38, güneş santralinde %21 düzeyindedir. Bağımsız denetim raporlarında olumlu görüş verilmiştir. Şirket, halka arz sonrasında yıllık dağıtılabilir dönem kârının en az %25'ini nakit kâr payı olarak dağıtmayı hedeflediğini kâr dağıtım politikasında belirtmiştir; ancak bu oran yatırım ihtiyaçlarına göre yönetim kurulu teklifiyle değiştirilebilir.",
 "yatirimci_iliskileri_sss": [
  {
   "soru": "Halka arzda kaç lot alabilirim?",
   "yanit": "Yurt içi bireysel yatırımcılara eşit dağıtım yöntemi uygulanmış olup dağıtım sonuçları aracı kurumunuz tarafından hesabınıza yansıtılmıştır. Kesin dağıtım listeleri konsorsiyum lideri tarafından yayımlanmıştır."
  },
  {
   "soru": "Ödediğim fazla tutar ne zaman iade edilir?",
   "yanit": "Dağıtım sonrasında karşılanmayan taleplere ait bloke tutarlar, talepte bulunduğunuz aracı kurum tarafından dağıtım listelerinin onaylanmasını takiben serbest bırakılmıştır."
  },
  {
   "soru": "Şirketin kâr payı politikası nedir?",
   "yanit": "Kâr dağıtım politikası izahnamede ve şirketin internet sitesinde yayımlanmıştır; kâr payı dağıtımına ilişkin kararlar her yıl genel kurul tarafından verilir."
  },
  {
   "soru": "Yeni güneş santrali ne zaman devreye girecek?",
   "yanit": "Proje için arazi tahsisi ve bağlantı görüşü alınmış olup inşaat sürecinin 2027 yılı içinde başlaması planlanmaktadır. Takvimdeki değişiklikler KAP aracılığıyla duyurulacaktır."
  },
  {
   "soru": "Paylar hangi endekslere girecek?",
   "yanit": "Endekslere dahil edilme, Borsa İstanbul'un endeks kurallarına ve dönemsel değerlendirmelerine bağlıdır; şirketin bu konuda bir taahhüdü bulunmamaktadır."
  }
 ],
 "konsorsiyum_ve_takvim": "Halka arz, Lodos Yatırım Menkul Değerler A.Ş. liderliğinde 31 aracı kurumdan oluşan bir konsorsiyum tarafından yürütülmüştür. SPK onayı 20.08.2026 tarihli bültende yayımlanmış, yatırımcı sunumları 21-22 Ağustos'ta İstanbul ve Londra'da yapılmıştır. Talep toplama 25-27 Ağustos, dağıtım sonuçlarının ilanı 28 Ağustos, ilk işlem günü ise 1 Eylül olarak gerçekleşmiştir. Bağımsız denetim Kalkan Denetim ve YMM A.Ş., hukukçu raporu ise Ertunç Hukuk Bürosu tarafından hazırlanmıştır.",
 "basin_ozeti": [
  "Ekonomi gazetesi (29.08.2026): Yılın en kalabalık halka arzlarından biri olarak gösterilen işlemde katılımcı sayısının 1,6 milyonu aşması, bireysel yatırımcıların enerji sektörüne ilgisinin sürdüğüne yorumlandı. Haberde, şirket genel müdürünün halka arz gelirinin önemli kısmının yeni yatırımlara ayrılacağını söylediği aktarıldı.",
  "Sektör bülteni (05.09.2026): Rüzgâr santrallerinde ağustos ayı üretiminin mevsim normallerinin altında kaldığı, bunun sektör genelinde üçüncü çeyrek hasılatlarını sınırlayabileceği belirtildi. Bültende ayrıca iletim şirketinin yeni trafo merkezi yatırımları ve kapasite tahsis yarışmalarının takvimine ilişkin bilgiler yer aldı.",
  "Yerel gazete (12.09.2026): Şirketin Çanakkale'deki santralinin bulunduğu köyde düzenlenen etkinlikte, yerel üreticilere yönelik tarımsal sulama projesine destek verileceği açıklandı. Etkinliğe belediye başkanı ve köy muhtarları katıldı.",
  "Finans portalı (24.09.2026): Halka arz sonrası ilk ayda payların günlük ortalama işlem hacminin 1,1 milyar TL civarında gerçekleştiği, hacmin ilk haftadan sonra belirgin biçimde azaldığı yazıldı. Haberde, analistlerin büyük bölümünün şirket için henüz hedef fiyat yayımlamadığı belirtildi."
 ]
}
